def normalize(path):
    """A slash-separated path in its shortest form. See TASK.md."""
    absolute = path.startswith("/")
    stack = []
    for seg in path.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not absolute:
                stack.append("..")
            # absolute and nothing to remove: `..` at the root is dropped
        else:
            stack.append(seg)
    body = "/".join(stack)
    if absolute:
        return "/" + body
    return body or "."


def join(base, *parts):
    """`base` with each part applied, normalised. See TASK.md."""
    cur = base
    for part in parts:
        if part == "":
            continue
        if part.startswith("/") or cur == "":
            cur = part
        else:
            cur = cur + "/" + part
    return normalize(cur)
